import hmac
import json
import re

from payhook.errors import InvalidNotification

_TIMESTAMP_HEADER = "x-pay-timestamp"
_SIGNATURE_HEADER = "x-pay-signature"
_RECEIPT_HEADER = "x-pay-receipt"

_TIMESTAMP_RE = re.compile(r"-?[0-9]+")
_CURRENCY_RE = re.compile(r"[A-Z]{3}")
_MAX_DRIFT_SECONDS = 300


def _get_header(headers, name):
    """Case-insensitively look up a header value, or None if absent."""
    for key, value in headers.items():
        if isinstance(key, str) and key.lower() == name:
            return value
    return None


def _parse_timestamp(headers):
    """Return the raw timestamp string after validating it is decimal."""
    raw = _get_header(headers, _TIMESTAMP_HEADER)
    if not isinstance(raw, str) or _TIMESTAMP_RE.fullmatch(raw) is None:
        raise InvalidNotification("missing or malformed X-Pay-Timestamp")
    return raw


def _parse_event(raw_body):
    """Validate the JSON body and return (event_id, account_id, amount_minor, currency)."""
    if isinstance(raw_body, str):
        raw_body = raw_body.encode("utf-8")
    try:
        event = json.loads(raw_body.decode("utf-8"))
    except (UnicodeDecodeError, ValueError) as exc:
        raise InvalidNotification("malformed JSON body") from exc
    if not isinstance(event, dict):
        raise InvalidNotification("body must be a JSON object")

    event_id = event.get("event_id")
    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("event_id must be a nonempty string")

    account_id = event.get("account_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("account_id must be a nonempty string")

    amount_minor = event.get("amount_minor")
    if (
        isinstance(amount_minor, bool)
        or not isinstance(amount_minor, int)
        or amount_minor < 0
    ):
        raise InvalidNotification("amount_minor must be a nonnegative integer")

    currency = event.get("currency")
    if not isinstance(currency, str) or _CURRENCY_RE.fullmatch(currency) is None:
        raise InvalidNotification("currency must be three uppercase ASCII letters")

    return event_id, account_id, amount_minor, currency


def _digest(secret, payload):
    return hmac.new(secret, payload, hashlib.sha256).hexdigest()


def _matches(header_value, prefix, expected_hex):
    """Constant-time check that a ``scheme=<hex>`` header carries expected_hex."""
    if not isinstance(header_value, str) or not header_value.startswith(prefix):
        return False
    received = header_value[len(prefix):].encode("utf-8", "replace")
    return hmac.compare_digest(received, expected_hex.encode("ascii"))


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    if isinstance(secret, str):
        secret = secret.encode("utf-8")

    timestamp = _parse_timestamp(headers)
    try:
        stamp = int(timestamp)
    except ValueError as exc:
        raise InvalidNotification("malformed X-Pay-Timestamp") from exc
    if abs(stamp - now) > _MAX_DRIFT_SECONDS:
        raise InvalidNotification("timestamp outside the acceptance window")

    event_id, account_id, amount_minor, currency = _parse_event(raw_body)

    # v1: HMAC over the ASCII timestamp, ".", and the exact received body bytes.
    v1_expected = _digest(secret, timestamp.encode("ascii") + b"." + raw_body)
    v1_ok = _matches(_get_header(headers, _SIGNATURE_HEADER), "v1=", v1_expected)

    if not v1_ok:
        # r0 (legacy v0 connector receipt): HMAC over the ASCII timestamp, ".",
        # and the UTF-8 event_id. The v0 relay reformats bodies, so the body
        # digest is unavailable; the event-id receipt is the stable identity
        # proof, and a matching receipt plus an in-window timestamp suffices.
        r0_expected = _digest(
            secret, timestamp.encode("ascii") + b"." + event_id.encode("utf-8")
        )
        if not _matches(_get_header(headers, _RECEIPT_HEADER), "r0=", r0_expected):
            raise InvalidNotification("missing or invalid signature or receipt")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }
"}
